            /// <summary>Starts the thread: run() on a new .NET thread (once per Thread object).</summary>
            public void start()
            {
                lock (_started)
                {
                    if (_thread != null) throw new InvalidOperationException("threads can only be started once");
                    _thread = new global::System.Threading.Thread(Bootstrap, (int)Math.Min(int.MaxValue, _stackSize)) { IsBackground = _daemonic, Name = _name };
                }
                lock (Registry) Limbo.Add(this);
                try { _thread.Start(); }
                catch (Exception)
                {
                    lock (Registry) Limbo.Remove(this);
                    throw;
                }
                _started.Wait();
            }

            void Bootstrap()
            {
                _current = this;
                _ident = Environment.CurrentManagedThreadId;
                _native_id = PyWait.NativeId();
                contextvars.EnterThread();
                lock (Registry) { Limbo.Remove(this); Active[_ident.Value] = this; }
                _started.Set();
                try { run(); }
                catch (Exception e) { InvokeExcepthook(e); }
                finally
                {
                    lock (Registry) Active.Remove(_ident.Value);
                    _done = true;
                }
            }

            internal void InvokeExcepthook(Exception e)
            {
                try { PyWait.Call(excepthook, new object?[] { new ExceptHookArgs(e.GetType(), e, null, this) }); }
                catch (Exception hookError) { PyWait.Unraisable("Exception in threading.excepthook:", hookError); }
            }

            /// <summary>The thread's activity: calls target(*args, **kwargs). Subclasses override it.</summary>
            public virtual void run()
            {
                try { if (_target != null) PyWait.Call(_target, _args, _kwargs); }
                finally { _target = null; _args = Array.Empty<object?>(); _kwargs = null; }
            }

            /// <summary>Waits until the thread ends (or the timeout passes: then is_alive() tells whether it ended).</summary>
            public void join(double? timeout = null)
            {
                var t = _thread;
                if (t == null || !_started.IsSet) throw new InvalidOperationException("cannot join thread before it is started");
                if (t == global::System.Threading.Thread.CurrentThread) throw new InvalidOperationException("cannot join current thread");
                t.Join(PyWait.Span(timeout));
            }

            public virtual bool is_alive() => _started.IsSet && !_done && _thread != null && _thread.IsAlive;

            public string name
            {
                get => _name;
                set
                {
                    _name = Builtins.str(value);
                    try { if (_thread != null) _thread.Name = _name; } catch (InvalidOperationException) { }
                }
            }

            public long? ident => _ident;
            public long? native_id => _native_id;

            public bool daemon
            {
                get => _daemonic;
                set
                {
                    if (_started.IsSet) throw new InvalidOperationException("cannot set daemon status of active thread");
                    _daemonic = value;
                }
            }

            // the old camelCase names (deprecated in Python)
            public bool isDaemon() => daemon;
            public void setDaemon(bool daemonic) => daemon = daemonic;
            public string getName() => name;
            public void setName(object? name) => this.name = Builtins.str(name);

            public string __repr__()
            {
                string status = _done || (_started.IsSet && _thread != null && !_thread.IsAlive) ? "stopped" : _started.IsSet ? "started" : "initial";
                if (_daemonic) status += " daemon";
                if (_ident != null) status += " " + _ident;
                return $"<{Builtins.PyTypeName(GetType())}({_name}, {status})>";
            }
            public override string ToString() => __repr__();
        }

        /// <summary>The thread the program started on (the thread that first used threading).</summary>
        internal sealed class _MainThread : Thread
        {
            public _MainThread() : base(default(Running), "MainThread", false) { }
        }

        /// <summary>A thread threading did not start (a .NET or thread-pool thread): always alive, daemonic, not joinable.</summary>
        internal sealed class _DummyThread : Thread
        {
            public _DummyThread() : base(default(Running), NewName("Dummy-"), true) { }
            public override bool is_alive() => true;
        }

        /// <summary>threading.Timer(interval, function, args=None, kwargs=None): calls the function after the interval unless cancelled.</summary>
        internal class Timer : Thread
        {
            public double interval;
            public object? function;
            public object? args;
            public object? kwargs;
            public readonly Event finished = new Event();

            public Timer(double interval, object? function, object? args = null, object? kwargs = null)
            {
                this.interval = interval;
                this.function = function;
                this.args = args;
                this.kwargs = kwargs;
            }

            /// <summary>Stops the timer if it has not called the function yet.</summary>
            public void cancel() => finished.set();

            public override void run()
            {
                finished.wait(interval);
                if (!finished.is_set()) PyWait.Call(function, PyWait.Args(args), PyWait.Kwargs(kwargs));
                finished.set();
            }
        }

        /// <summary>threading.local(): attributes whose values each thread has its own of (a fresh object in a new thread).</summary>
        internal class local : System.Dynamic.DynamicObject, IPyRepr
        {
            readonly global::System.Threading.ThreadLocal<Dictionary<string, object?>> _values =
                new global::System.Threading.ThreadLocal<Dictionary<string, object?>>(() => new Dictionary<string, object?>());

            public override bool TryGetMember(System.Dynamic.GetMemberBinder binder, out object? result)
            {
                if (_values.Value!.TryGetValue(binder.Name, out result)) return true;
                if (binder.Name == "__dict__") { result = new OrderedDictionary<string, object?>(_values.Value!); return true; }
                throw new MissingMemberException($"'_thread._local' object has no attribute '{binder.Name}'");
            }

            public override bool TrySetMember(System.Dynamic.SetMemberBinder binder, object? value)
            {
                _values.Value![binder.Name] = value;
                return true;
            }

            public override bool TryDeleteMember(System.Dynamic.DeleteMemberBinder binder) =>
                _values.Value!.Remove(binder.Name) ? true : throw new MissingMemberException(binder.Name);

            public override IEnumerable<string> GetDynamicMemberNames() => _values.Value!.Keys.ToList();
            public string __repr__() => $"<_thread._local object at {PyWait.Address(this)}>";
            public override string ToString() => __repr__();
        }

        /// <summary>threading.serialize_iterator(iterable): an iterator that threads can share (next() under a lock).</summary>
        internal class serialize_iterator : IEnumerable<object?>, IEnumerator<object?>
        {
            readonly IEnumerator _it;
            readonly object _lock = new object();
            object? _current;

            public serialize_iterator(object? iterable)
            {
                _it = iterable is IEnumerable e ? e.GetEnumerator() : iterable as IEnumerator ?? throw new InvalidCastException($"'{Builtins.PyTypeName(iterable?.GetType() ?? typeof(object))}' object is not iterable");
            }

            public bool MoveNext()
            {
                lock (_lock)
                {
                    if (!_it.MoveNext()) return false;
                    _current = _it.Current is char c ? c.ToString() : _it.Current;
                    return true;
                }
            }

            public object? Current => _current;
            public void Reset() => throw new NotSupportedException();
            public void Dispose() { }
            public IEnumerator<object?> GetEnumerator() => this;
            IEnumerator IEnumerable.GetEnumerator() => this;
            public dynamic? __next__() => MoveNext() ? _current : throw new StopIteration();
        }

        /// <summary>threading.synchronized_iterator(func): func whose iterators are serialize_iterators.</summary>
        public static dynamic synchronized_iterator(object? func) =>
            new PyClosure(PyWait.NameOf(func) ?? "inner", (a, kw) => new serialize_iterator(PyWait.Call(func, a, kw)));

        /// <summary>threading.concurrent_tee(iterable, n=2): n independent iterators over one iterator, safe to fill from several threads.</summary>
        public static PyTuple<object?> concurrent_tee(object? iterable, long n = 2)
        {
            if (n < 0) throw new ArgumentException("n must be a non-negative integer");
            var shared = new TeeSource(iterable);
            return new PyTuple<object?>(Enumerable.Range(0, (int)n).Select(_ => (object?)shared.Branch()).ToArray());
        }

        sealed class TeeSource
        {
            readonly IEnumerator _it;
            readonly List<object?> _buffer = new List<object?>();
            bool _ended;
            public TeeSource(object? iterable) { _it = iterable is IEnumerable e ? e.GetEnumerator() : (IEnumerator)iterable!; }
            public IEnumerable<object?> Branch()
            {
                for (int i = 0; ; i++)
                {
                    object? item;
                    lock (_buffer)
                    {
                        if (i >= _buffer.Count)
                        {
                            if (_ended || !_it.MoveNext()) { _ended = true; yield break; }
                            _buffer.Add(_it.Current is char c ? c.ToString() : _it.Current);
                        }
                        item = _buffer[i];
                    }
                    yield return item;
                }
            }
        }

        // ── the module's functions ──

        public static Thread current_thread() => Thread.Current;
        public static Thread currentThread() => Thread.Current;
        public static Thread main_thread() => Thread.Main;
        public static long get_ident() => Environment.CurrentManagedThreadId;
        public static long get_native_id() => PyWait.NativeId();

        /// <summary>The Thread objects alive now: the main thread, started threads that have not ended, dummy threads.</summary>
        public static List<Thread> enumerate()
        {
            _ = Thread.Main;
            lock (Thread.Registry) return Thread.Active.Values.Where(t => t.is_alive()).Concat(Thread.Limbo).ToList();
        }

        public static long active_count() => enumerate().Count;
        public static long activeCount() => active_count();

        /// <summary>The original threading.excepthook: "Exception in thread NAME:" and the traceback on stderr (SystemExit: nothing).</summary>
        public static readonly Action<ExceptHookArgs> __excepthook__ = DefaultExcepthook;

        /// <summary>threading.excepthook(args): what happens to an exception that leaves a thread's run() (assignable).</summary>
        public static dynamic excepthook = __excepthook__;

        static void DefaultExcepthook(ExceptHookArgs args)
        {
            if (args.exc_value is SystemExit) return;
            if (args.exc_value is not Exception error) throw new InvalidCastException("exc_value must be an exception");
            string name = args.thread is object target ? Builtins.str((object?)Builtins.getattr(target, "name")) : get_ident().ToString();
            object output = (object?)sys_.stderr ?? sys_.__stderr__;
            Builtins.print_kw([$"Exception in thread {name}:"], file: output);
            Builtins.print_kw([PyExcInfo.Format(error)], file: output, flush: true);
        }

        // sys.settrace / sys.setprofile for threads: Typhon has no tracing hooks (the functions are kept, not called)
        static object? _traceHook, _profileHook;
        public static void settrace(object? func) => _traceHook = func;
        public static void settrace_all_threads(object? func) => _traceHook = func;
        public static dynamic? gettrace() => _traceHook;
        public static void setprofile(object? func) => _profileHook = func;
        public static void setprofile_all_threads(object? func) => _profileHook = func;
        public static dynamic? getprofile() => _profileHook;

        /// <summary>The stack size of threads started from now on (0: the platform's default); the previous size.</summary>
        public static long stack_size(long size = 0)
        {
            if (size != 0 && size < 32768) throw new ArgumentException("size not valid: " + size + " bytes");
            long old = _stackSize;
            _stackSize = size;
            return old;
        }
    }

    /// <summary>_thread: the low-level thread functions threading builds on.</summary>
    internal static partial class _thread
    {
        public static readonly double TIMEOUT_MAX = PyWait.TimeoutMax;

        /// <summary>_thread.error (RuntimeError in Python).</summary>
        internal class error : InvalidOperationException { public error(string message = "") : base(message) { } }
        internal sealed class LockType : threading.Lock { }
        internal sealed class RLock : threading.RLock { }
        internal sealed class _local : threading.local { }
        internal sealed class _ExceptHookArgs : threading.ExceptHookArgs
        {
            public _ExceptHookArgs(object? sequence) : this(Items(sequence)) { }
            _ExceptHookArgs(object?[] values) : base(values[0], values[1], values[2], values[3]) { }

            static object?[] Items(object? sequence)
            {
                if (sequence is not (System.Collections.IEnumerable or System.Runtime.CompilerServices.ITuple))
                    throw new InvalidCastException("constructor requires a sequence");
                var values = Builtins.__iter_dyn(sequence).ToArray();
                if (values.Length != 4)
                    throw new InvalidCastException($"_thread._ExceptHookArgs() takes a 4-sequence ({values.Length}-sequence given)");
                return values;
            }
        }

        public static LockType allocate_lock() => new LockType();
        public static LockType allocate() => new LockType();
        public static long get_ident() => Environment.CurrentManagedThreadId;
        public static long get_native_id() => PyWait.NativeId();
        public static bool daemon_threads_allowed() => true;
        public static long stack_size(long size = 0) => threading.stack_size(size);
        public static long _count() => global::System.Threading.Interlocked.Read(ref _running);
        static long _running;

        /// <summary>
        /// _thread.start_new_thread(function, args, kwargs=None): runs function(*args, **kwargs) on a new background thread;
        /// its ident. An exception it raises is printed on stderr.
        /// </summary>
        public static long start_new_thread(object? function, object? args, object? kwargs = null)
        {
            if (args is not global::System.Runtime.CompilerServices.ITuple) throw new InvalidCastException("2nd arg must be a tuple");
            var a = PyWait.Args(args);
            var kw = PyWait.Kwargs(kwargs);
            var t = new global::System.Threading.Thread(() =>
            {
                contextvars.EnterThread();
                global::System.Threading.Interlocked.Increment(ref _running);
                try { PyWait.Call(function, a, kw); }
                catch (SystemExit) { }
                catch (Exception e) { PyWait.Unraisable($"Exception ignored in thread started by: {Builtins.repr(function)}", e); }
                finally { global::System.Threading.Interlocked.Decrement(ref _running); }
            }) { IsBackground = true };
            t.Start();
            return t.ManagedThreadId;
        }

        public static long start_new(object? function, object? args, object? kwargs = null) => start_new_thread(function, args, kwargs);

        /// <summary>_thread.exit(): ends the current thread (raises SystemExit, which a thread's end ignores).</summary>
        public static void exit() => throw new SystemExit();
        public static void exit_thread() => throw new SystemExit();
        public static dynamic _excepthook = threading.excepthook;
    }

    /// <summary>
    /// queue: Queue (FIFO), LifoQueue, PriorityQueue (lowest first, by Python's ordering) and SimpleQueue for passing
    /// items between threads: put / get with block and timeout, task_done / join, shutdown, and the Empty / Full / ShutDown
    /// exceptions. After CPython's Lib/queue.py (one mutex and three conditions).
    /// </summary>
    internal static class queue
    {
        internal class Empty : _queue.Empty { public Empty(string message = "") : base(message) { } }
        internal class Full : Exception { public Full(string message = "") : base(message) { } }
        internal class ShutDown : Exception { public ShutDown(string message = "") : base(message) { } }

        /// <summary>queue.Queue(maxsize=0): first in, first out; maxsize &gt; 0 bounds it (put waits while it is full).</summary>
        internal class Queue
        {
            public long maxsize;
            public readonly threading.Lock mutex = new threading.Lock();
            public readonly threading.Condition not_empty, not_full, all_tasks_done;
            public long unfinished_tasks;
            public bool is_shutdown;
            /// <summary>The items (a deque for Queue, a list for LifoQueue and PriorityQueue), as CPython's queue attribute.</summary>
            public dynamic? queue;

            /// <summary>(a subclass without __init__ inherits the constructors without their defaults: MyQueue() calls this one)</summary>
            public Queue() : this(0L) { }

            public Queue(long maxsize)
            {
                this.maxsize = maxsize;
                _init(maxsize);
                not_empty = new threading.Condition(mutex);
                not_full = new threading.Condition(mutex);
                all_tasks_done = new threading.Condition(mutex);
            }

            // the storage, which subclasses override
            public virtual void _init(object? maxsize) => queue = new deque<object?>();
            public virtual long _qsize() => ((deque<object?>)queue!).Count;
            public virtual void _put(object? item) => ((deque<object?>)queue!).append(item);
            public virtual dynamic? _get() => ((deque<object?>)queue!).popleft();

            /// <summary>A consumer's signal that it finished an item it got; join() returns once every item put is done.</summary>
            public void task_done()
            {
                all_tasks_done.acquire();
                try
                {
                    long unfinished = unfinished_tasks - 1;
                    if (unfinished <= 0)
                    {
                        if (unfinished < 0) throw new ArgumentException("task_done() called too many times");
                        all_tasks_done.notify_all();
                    }
                    unfinished_tasks = unfinished;
                }
                finally { all_tasks_done.release(); }
            }

            /// <summary>Waits until every item put has been got and marked done (task_done).</summary>
            public void join()
            {
                all_tasks_done.acquire();
                try { while (unfinished_tasks != 0) all_tasks_done.wait(); }
                finally { all_tasks_done.release(); }
            }

            public long qsize() { mutex.acquire(); try { return _qsize(); } finally { mutex.release(); } }
            public bool empty() { mutex.acquire(); try { return _qsize() == 0; } finally { mutex.release(); } }
            public bool full() { mutex.acquire(); try { return 0 < maxsize && maxsize <= _qsize(); } finally { mutex.release(); } }

            /// <summary>Adds an item; a full bounded queue waits (block=True, up to timeout seconds) or raises Full.</summary>
            public void put(object? item, bool block = true, double? timeout = null)
            {
                not_full.acquire();
                try
                {
                    if (is_shutdown) throw new ShutDown();
                    if (maxsize > 0)
                    {
                        if (!block) { if (_qsize() >= maxsize) throw new Full(); }
                        else if (timeout == null)
                        {
                            while (_qsize() >= maxsize)
                            {
                                not_full.wait();
                                if (is_shutdown) throw new ShutDown();
                            }
                        }
                        else if (timeout < 0) throw new ArgumentException("'timeout' must be a non-negative number");
                        else
                        {
                            long end = PyWait.Deadline(timeout.Value);
                            while (_qsize() >= maxsize)
                            {
                                double remaining = PyWait.Left(end);
                                if (remaining <= 0.0) throw new Full();
                                not_full.wait(remaining);
                                if (is_shutdown) throw new ShutDown();
                            }
                        }
                    }
                    _put(item);
                    unfinished_tasks++;
                    not_empty.notify();
                }
                finally { not_full.release(); }
            }

            /// <summary>Removes and returns an item; an empty queue waits (block=True, up to timeout seconds) or raises Empty.</summary>
            public dynamic? get(bool block = true, double? timeout = null)
            {
                not_empty.acquire();
                try
                {
                    if (is_shutdown && _qsize() == 0) throw new ShutDown();
                    if (!block) { if (_qsize() == 0) throw new Empty(); }
                    else if (timeout == null)
                    {
                        while (_qsize() == 0)
                        {
                            not_empty.wait();
                            if (is_shutdown && _qsize() == 0) throw new ShutDown();
                        }
                    }
                    else if (timeout < 0) throw new ArgumentException("'timeout' must be a non-negative number");
                    else
                    {
                        long end = PyWait.Deadline(timeout.Value);
                        while (_qsize() == 0)
                        {
                            double remaining = PyWait.Left(end);
                            if (remaining <= 0.0) throw new Empty();
                            not_empty.wait(remaining);
                            if (is_shutdown && _qsize() == 0) throw new ShutDown();
                        }
                    }
                    object? item = _get();
                    not_full.notify();
                    return item;
                }
                finally { not_empty.release(); }
            }

            public void put_nowait(object? item) => put(item, false);
            public dynamic? get_nowait() => get(false);

            /// <summary>Shuts the queue down: put raises ShutDown, get too once it is empty (immediate=True empties it now).</summary>
            public void shutdown(bool immediate = false)
            {
                mutex.acquire();
                try
                {
                    is_shutdown = true;
                    if (immediate)
                    {
                        while (_qsize() > 0)
                        {
                            _get();
                            if (unfinished_tasks > 0) unfinished_tasks--;
                        }
                        all_tasks_done.notify_all();
                    }
                    not_empty.notify_all();
                    not_full.notify_all();
                }
                finally { mutex.release(); }
            }
        }

        /// <summary>queue.LifoQueue: last in, first out.</summary>
        internal class LifoQueue : Queue
        {
            public LifoQueue() : base(0L) { }
            public LifoQueue(long maxsize) : base(maxsize) { }
            public override void _init(object? maxsize) => queue = new List<object?>();
            public override long _qsize() => ((List<object?>)queue!).Count;
            public override void _put(object? item) => ((List<object?>)queue!).Add(item);
            public override dynamic? _get()
            {
                var items = (List<object?>)queue!;
                var item = items[items.Count - 1];
                items.RemoveAt(items.Count - 1);
                return item;
            }
        }

        /// <summary>queue.PriorityQueue: the lowest item first (Python's ordering: put (priority, data) tuples), a binary heap.</summary>
        internal class PriorityQueue : Queue
        {
            public PriorityQueue() : base(0L) { }
            public PriorityQueue(long maxsize) : base(maxsize) { }
            public override void _init(object? maxsize) => queue = new List<object?>();
            public override long _qsize() => ((List<object?>)queue!).Count;
            public override void _put(object? item) => heapq.heappush((List<object?>)queue!, item);
            public override dynamic? _get() => heapq.heappop((List<object?>)queue!);
        }

        /// <summary>queue.SimpleQueue: an unbounded FIFO queue without task tracking.</summary>
        internal class SimpleQueue
        {
            readonly global::System.Collections.Generic.Queue<object?> _items = new global::System.Collections.Generic.Queue<object?>();

            public void put(object? item, bool block = true, double? timeout = null)
            {
                lock (_items)
                {
                    _items.Enqueue(item);
                    global::System.Threading.Monitor.Pulse(_items);
                }
            }

            public void put_nowait(object? item) => put(item, false);

            public dynamic? get(bool block = true, double? timeout = null)
            {
                if (timeout < 0) throw new ArgumentException("'timeout' must be a non-negative number");
                lock (_items)
                {
                    if (_items.Count == 0 && (!block || !PyWait.Until(_items, () => _items.Count > 0, timeout))) throw new Empty();
                    return _items.Dequeue();
                }
            }

            public dynamic? get_nowait() => get(false);
            public bool empty() { lock (_items) return _items.Count == 0; }
            public long qsize() { lock (_items) return _items.Count; }
        }
    }

    /// <summary>_queue: the C part of queue in CPython (SimpleQueue and Empty).</summary>
    internal static class _queue
    {
        internal class Empty : Exception { public Empty(string message = "") : base(message) { } }
        internal sealed class SimpleQueue : queue.SimpleQueue { }
    }
}
